"""Typed campaign record parsing and revision-aware reconciliation."""
from common import (COLUMNS, MAX_TIME, Invalid, address, decimal, decode64,
                    ident)


class Record:
    """A validated logical record, with a canonical semantic content key."""
    __slots__ = ('typ', 'rid', 'rev', 'pub', 'op', 'content', 'lease',
                 'event', 'probe', 'target', 'responder', 'result',
                 'service', 'attempt', 'payload', 'canary')

    def __init__(self, typ, rid, rev, pub, op, content, lease=None, event=None,
                 probe=None, target=None, responder=None, result=None,
                 service=None, attempt=None, payload=b'', canary=False):
        self.typ = typ
        self.rid = rid
        self.rev = rev
        self.pub = pub
        self.op = op
        self.content = content
        self.lease = lease
        self.event = event
        self.probe = probe
        self.target = target
        self.responder = responder
        self.result = result
        self.service = service
        self.attempt = attempt
        self.payload = payload
        self.canary = canary


def _delete_content(typ):
    return (typ, 'delete')


def parse_record(values, context, lookup):
    """Parse one 14-field CSV row.  Any logical failure raises Invalid."""
    if len(values) != 14:
        raise Invalid('wrong field count')
    (typ, rid, revision_text, published_text, op, lease, event_text, probe,
     target_text, responder_text, result, service, attempt_text,
     payload_text) = values

    if typ not in ('icmp', 'app'):
        raise Invalid('bad record type')
    if not ident(rid):
        raise Invalid('bad record id')
    revision = decimal(revision_text, 10 ** 9)
    published = decimal(published_text, MAX_TIME)
    if op not in ('put', 'delete'):
        raise Invalid('bad operation')

    if op == 'delete':
        if any(value != '' for value in values[5:]):
            raise Invalid('nonempty delete field')
        return Record(typ, rid, revision, published, op,
                      _delete_content(typ))

    leases = context['leases']
    if lease not in leases:
        raise Invalid('unknown lease')
    lease_row = leases[lease]
    event = decimal(event_text, MAX_TIME)
    if not (lease_row['start'] <= event < lease_row['end']):
        raise Invalid('event outside lease')
    if event > published:
        raise Invalid('event after publication')

    target = address(target_text)

    if typ == 'icmp':
        lease_lookup = lookup.get(lease)
        if lease_lookup is None or probe not in lease_lookup:
            raise Invalid('unknown probe')
        planned, canary = lease_lookup[probe]
        if target != planned:
            raise Invalid('probe/target mismatch')
        if result not in ('echo', 'error', 'timeout'):
            raise Invalid('bad ICMP result')
        if result == 'timeout':
            if responder_text != '':
                raise Invalid('timeout responder')
            responder = None
        else:
            responder = address(responder_text)
        if service != '' or attempt_text != '' or payload_text != '':
            raise Invalid('nonempty ICMP application field')
        content = (typ, 'put', lease, event, probe, target, responder,
                   result, '', None, b'')
        return Record(typ, rid, revision, published, op, content,
                      lease=lease, event=event, probe=probe, target=target,
                      responder=responder, result=result, service='',
                      attempt=None, payload=b'', canary=canary)

    # Application put.
    if probe != '' or responder_text != '':
        raise Invalid('nonempty app probe/responder')
    if service not in context['services']:
        raise Invalid('unknown service')
    attempt = decimal(attempt_text, 10 ** 6)
    if result not in ('open', 'closed', 'timeout'):
        raise Invalid('bad application result')
    payload = decode64(payload_text, Invalid)
    if len(payload) > 65536:
        raise Invalid('payload too large')
    kind = context['services'][service]
    if result in ('closed', 'timeout') and payload:
        raise Invalid('payload on closed/timeout')
    if kind == 'tcp' and payload:
        raise Invalid('payload on TCP')
    content = (typ, 'put', lease, event, '', target, None, result,
               service, attempt, payload)
    return Record(typ, rid, revision, published, op, content,
                  lease=lease, event=event, probe='', target=target,
                  responder=None, result=result, service=service,
                  attempt=attempt, payload=payload, canary=False)


def group_records(records):
    groups = {}
    for record in records:
        key = (record.typ, record.rid)
        bucket = groups.get(key)
        if bucket is None:
            groups[key] = [record]
        else:
            bucket.append(record)
    return groups


def reconcile(groups, query):
    """Reconcile all identities at one query.

    Returns ((live, deleted, conflict), live_icmp_records, live_app_records).
    """
    live = deleted = conflict = 0
    live_icmp = []
    live_app = []
    for records in groups.values():
        count = len(records)
        if count == 1:
            record = records[0]
            if record.pub > query:
                continue
            if record.op == 'delete':
                deleted += 1
            else:
                if record.typ == 'icmp':
                    live_icmp.append(record)
                else:
                    live_app.append(record)
                live += 1
            continue

        max_revision = -1
        contents = None
        for record in records:
            if record.pub > query:
                continue
            revision = record.rev
            if revision > max_revision:
                max_revision = revision
                contents = {record.content: record}
            elif revision == max_revision:
                if record.content not in contents:
                    contents[record.content] = record
        if max_revision < 0:
            continue
        if len(contents) != 1:
            conflict += 1
            continue
        record = next(iter(contents.values()))
        if record.op == 'delete':
            deleted += 1
        else:
            if record.typ == 'icmp':
                live_icmp.append(record)
            else:
                live_app.append(record)
            live += 1
    return (live, deleted, conflict), live_icmp, live_app


class Ledger:
    """Convenience wrapper used by the legacy tooling."""
    def __init__(self, records):
        self.groups = group_records(records)

    def at(self, time):
        return reconcile(self.groups, time)
PY
